  SELECT string_agg(g.fact_id::text, ', ') INTO bad FROM g
   WHERE NOT EXISTS (SELECT 1 FROM player_facts f WHERE f.id = g.fact_id AND f.player_id IS NULL
                       AND f.player_name = g.player_name AND f.fact_type = g.fact_type AND f.fact_value = g.fact_value);
  IF bad IS NOT NULL THEN RAISE EXCEPTION '018g: fact rows changed or already owned: %. Nothing changed.', bad; END IF;
  SELECT count(*) INTO n FROM backup_20260928_facts_018g;
  IF n <> 405 THEN RAISE EXCEPTION '018g: expected 405 fact rows, found %. Nothing changed.', n; END IF;
  SELECT string_agg(p.page_id::text, ', ') INTO bad FROM (VALUES (306190, 'Q1145222', 'gwynnto01'), (30242103, 'Q4912955', 'martibi01'), (9007085, 'Q5229698', 'roberda05'), (54378272, 'Q28057083', NULL), (73641632, 'Q114003684', NULL)) AS p(page_id, qid, sr_mlb)
   WHERE EXISTS (SELECT 1 FROM players x WHERE x.wikipedia_page_id = p.page_id OR x.wikidata_qid = p.qid OR (p.sr_mlb IS NOT NULL AND x.sr_mlb = p.sr_mlb));
  IF bad IS NOT NULL THEN RAISE EXCEPTION '018g: players already exist for pages %. Nothing changed.', bad; END IF;

  -- --- 2. NEW PLAYERS -----------------------------------------------------------------------
  INSERT INTO players (wikipedia_page_id, wikipedia_title, wikidata_qid, display_name, sports, sr_mlb, birth_year, positions, main_team, first_year, last_year)
  SELECT v.page_id, v.title, v.qid, v.display, ARRAY[v.sport], v.sr_mlb, v.birth_year, v.positions, v.main_team, v.first_year, v.last_year
    FROM (VALUES
    (306190, 'Tony Gwynn', 'Q1145222', 'Tony Gwynn', 'MLB', 'gwynnto01', 1960, 'OF', 'Padres', 1982, 2001),
    (30242103, 'Billy Martin (shortstop)', 'Q4912955', 'Billy Martin', 'MLB', 'martibi01', 1894, 'SS', 'Braves', 1914, 1914),
    (9007085, 'Dave Roberts (pitcher)', 'Q5229698', 'Dave Roberts', 'MLB', 'roberda05', 1944, 'P', 'Astros', 1969, 1981),
    (54378272, 'Elias Pettersson', 'Q28057083', 'Elias Pettersson', 'NHL', NULL, 1998, 'C', 'Canucks', 2018, 2026),
    (73641632, 'Elias Pettersson (ice hockey, born 2004)', 'Q114003684', 'Elias Pettersson', 'NHL', NULL, 2004, 'D', 'Canucks', 2024, 2026)
    ) AS v(page_id, title, qid, display, sport, sr_mlb, birth_year, positions, main_team, first_year, last_year);
  GET DIAGNOSTICS n = ROW_COUNT; IF n <> 5 THEN RAISE EXCEPTION '018g: expected 5 new players, got %', n; END IF;
  INSERT INTO player_aliases (player_id, alias, alias_exact, alias_norm, kind, source, curated)
  SELECT p.id, a.alias, normalize_name_exact(a.alias), normalize_name(a.alias), a.kind, a.source, a.source = 'curated'
    FROM (VALUES
    (306190, 'Tony Gwynn', 'title', 'wikipedia'),
    (30242103, 'Billy Martin (shortstop)', 'title', 'wikipedia'),
    (30242103, 'Billy Martin', 'display', 'wikipedia'),
    (9007085, 'Dave Roberts (pitcher)', 'title', 'wikipedia'),
    (9007085, 'Dave Roberts', 'display', 'wikipedia'),
    (54378272, 'Elias Pettersson', 'title', 'wikipedia'),
    (73641632, 'Elias Pettersson (ice hockey, born 2004)', 'title', 'wikipedia'),
    (73641632, 'Elias Pettersson', 'display', 'wikipedia'),
    (306190, 'Tony Gwynn Sr.', 'suffix_variant', 'curated')
    ) AS a(page_id, alias, kind, source)
    JOIN players p ON p.wikipedia_page_id = a.page_id
  ON CONFLICT (player_id, alias_exact) DO NOTHING;

