-- --- 6. CHECKS (run after COMMIT; one row; permanent tables and read-only calls) -----------------
SELECT
  (SELECT count(*) FROM players WHERE wikipedia_page_id IN (306190, 30242103, 9007085, 54378272, 73641632))                                  AS new_players,
  (SELECT count(*) FROM player_facts WHERE owner_method = 'open data (018g)')                              AS facts_owned,
  (SELECT count(*) FROM player_facts WHERE owner_method = 'open data (018g) shared')                       AS shared_copies,
  (SELECT count(*) FROM backup_20260928_deleted_facts_018g)                                                AS deleted,
  (SELECT count(*) FROM player_facts f JOIN backup_20260928_deleted_facts_018g b ON b.id = f.id)           AS deleted_still_present,
  (SELECT string_agg(sport || ' ' || player_name || ' ' || fact_type, '; ' ORDER BY sport, player_name, fact_type) FROM backup_20260928_deleted_facts_018g) AS deleted_list,
  (SELECT bool_and(relrowsecurity) FROM pg_class WHERE relname IN ('backup_20260928_facts_018g', 'backup_20260928_deleted_facts_018g')) AS backup_rls,
  (SELECT count(*) FROM information_schema.role_table_grants WHERE table_name IN ('backup_20260928_facts_018g', 'backup_20260928_deleted_facts_018g')
     AND grantee IN ('anon', 'authenticated'))                                                            AS backup_browser_grants,
  (SELECT string_agg(status || ':' || display_name, ' | ' ORDER BY display_name COLLATE "C") FROM resolve_player('Tony Gwynn', 'MLB'))  AS r_tony_gwynn,
  (SELECT string_agg(status || ':' || display_name, ' | ') FROM resolve_player('Tony Gwynn Sr.', 'MLB'))    AS r_tony_gwynn_sr,
  (SELECT string_agg(status || ':' || detail, ' | ' ORDER BY detail) FROM resolve_player('Elias Pettersson', 'NHL')) AS r_elias_pettersson,
  validate_answer_v2((SELECT id FROM players WHERE wikipedia_title = 'Tony Gwynn'), 'MLB',
    '[{"fact_type":"played_for_team","fact_value":"Padres"},{"fact_type":"mlb_hall_of_fame","fact_value":"true"}]'::jsonb)   AS v_gwynn_padres_hof,
  validate_answer_v2((SELECT id FROM players WHERE wikipedia_title = 'Frank Thomas'), 'MLB',
    '[{"fact_type":"played_for_team","fact_value":"White Sox"},{"fact_type":"mlb_500_home_runs","fact_value":"true"}]'::jsonb) AS v_big_hurt_sox_500hr,
  validate_answer_v2((SELECT id FROM players WHERE wikipedia_title = 'Frank Thomas'), 'MLB',
    '[{"fact_type":"played_for_team","fact_value":"Cubs"},{"fact_type":"mlb_mvp","fact_value":"true"}]'::jsonb)               AS v_big_hurt_cubs_mvp,
  validate_answer_v2((SELECT id FROM players WHERE wikipedia_title = 'Steve Young'), 'NFL',
    '[{"fact_type":"played_for_team","fact_value":"49ers"},{"fact_type":"nfl_super_bowl_winner","fact_value":"true"}]'::jsonb) AS v_steve_young_49ers_sb;
-- EXPECTED: new_players = 5; facts_owned = 395; shared_copies = 75; deleted = 10; deleted_still_present = 0; deleted_list = MLB Bernie Williams mlb_2500_career_hits; MLB Boog Powell mlb_40_hr_season; MLB Frank Thomas mlb_2500_career_hits; MLB Josh Smith mlb_silver_slugger; MLB Randy Johnson mlb_20_complete_game_season; MLB Tony Gwynn born_outside_us; NBA Bobby Jones nba_dpoy; NBA Corey Brewer nba_sixth_man_award; NHL Sebastian Aho nhl_100_playoff_points; NHL Stephane Richer nhl_100_playoff_points; backup_rls = true; backup_browser_grants = 0; r_tony_gwynn = ambiguous:Tony Gwynn | ambiguous:Tony Gwynn Jr.; r_tony_gwynn_sr = resolved:Tony Gwynn; r_elias_pettersson = ambiguous:2018-2026 <U+00B7> C <U+00B7> Canucks | ambiguous:2024-2026 <U+00B7> D <U+00B7> Canucks; v_gwynn_padres_hof = true; v_big_hurt_sox_500hr = true; v_big_hurt_cubs_mvp = false; v_steve_young_49ers_sb = true

